typedef float rational_t;

enum widget_dir_e { WDIR_Left, WDIR_Right };

class widget;

class color
{
public:
  float r, g, b, a;
  color(rational_t _r, rational_t _g, rational_t _b, rational_t _a)
    : r(_r), g(_g), b(_b), a(_a) {}
};

class stringx
{
  char *data;
public:
  stringx& operator=(const stringx&);
  const char *c_str() const;
};

class bar_widget
{
  char data[0x154];
public:
  bar_widget(const char *, widget *, short, short, widget_dir_e);
  virtual ~bar_widget();
};

class bitmap_widget
{
public:
  bitmap_widget(const char *, widget *, short, short, int);
  void open(const char *);
  void resize(rational_t, rational_t);
  void set_color(const color&);
};

class fluid_bar : public bar_widget
{
public:
  fluid_bar(const char *, widget *, short, short, widget_dir_e, rational_t, rational_t, const stringx&);
  virtual ~fluid_bar();
protected:
  bitmap_widget *bar_map;
  stringx name;
  rational_t w, h;
  rational_t full_val, to_val, cur_val, fill_rate, empty_rate, special_rate;
  rational_t old_full_val, old_to_val, old_cur_val, old_fill_rate, old_empty_rate;
  bool update, using_special_rate;
  color col[4];
};

#define NEW new

fluid_bar::fluid_bar( const char *_widget_name, widget *_parent, short _x, short _y, widget_dir_e _dir, rational_t _w, rational_t _h, const stringx& _name )
  : bar_widget( _widget_name, _parent, _x, _y, _dir )
{
  w = _w;
  h = _h;
  name = _name;
  full_val = old_full_val = 1.0f;
  to_val = old_to_val = 1.0f;
  cur_val = old_cur_val = 0.0f;
  fill_rate = empty_rate = special_rate = old_fill_rate = old_empty_rate = 1.0f;
  update = true;
  using_special_rate = false;
  col[0] = col[1] = col[2] = col[3] = color( 1.0f, 1.0f, 1.0f, 1.0f );

  bar_map = NEW bitmap_widget( "fluid-bar_map", this, 0, 0, 1 );
  bar_map->open( name.c_str() );
  bar_map->resize( w, h );
  bar_map->set_color( col[0] );
}
